"use client";
import { useRef } from "react";
import {
  useScrollMotion,
  type ScrollMotionProps,
  type ScrollEntranceOptions,
} from "./scroll-shared";
import { scrollEase, scrollStagger } from "./scroll-math";
export interface CounterProps extends ScrollMotionProps, ScrollEntranceOptions {
  value: number;
  from?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  variant?: "count" | "rolling";
  stagger?: number;
  format?: (value: number) => string;
}
export function Counter({
  value,
  from = 0,
  decimals = 0,
  prefix = "",
  suffix = "",
  variant = "count",
  stagger = 0.25,
  format,
  trigger = "enter",
  ...props
}: CounterProps) {
  const root = useRef<HTMLSpanElement>(null),
    digits = Math.max(0, Math.min(10, Math.floor(decimals))),
    target = Number.isFinite(value) ? value : 0,
    initial = Number.isFinite(from) ? from : 0;
  const display = (v: number) => (format ? format(v) : v.toFixed(digits)),
    final = display(target);
  const startingDigits = display(initial)
    .replace(/\D/g, "")
    .padStart(final.replace(/\D/g, "").length, "0")
    .slice(-final.replace(/\D/g, "").length);
  useScrollMotion(
    root,
    { ...props, trigger },
    ({ progress: p }) => {
      const el = root.current!,
        current = initial + (target - initial) * scrollEase(p);
      el.dataset.value = String(current);
      if (variant === "count")
        el.querySelector<HTMLElement>("[data-scroll-count]")!.textContent = display(current);
      else {
        const columns = el.querySelectorAll<HTMLElement>("[data-scroll-digit]");
        columns.forEach((col, i) => {
          const digit = Number(col.dataset.scrollDigit),
            q = scrollEase(scrollStagger(p, i, columns.length, stagger)),
            startDigit = Number(startingDigits[i] ?? 0);
          col.style.transform = `translateY(${(-(startDigit + (10 + digit - startDigit) * q) * 100) / 20}%)`;
        });
      }
    },
    `${target}:${initial}:${digits}:${prefix}:${suffix}:${variant}:${stagger}:${final}`,
  );
  return (
    <span
      ref={root}
      data-scroll-animation="counter"
      className={props.className}
      aria-label={`${prefix}${final}${suffix}`}
      style={{
        display: "inline-flex",
        alignItems: "baseline",
        fontVariantNumeric: "tabular-nums",
        whiteSpace: "nowrap",
        ...props.style,
      }}
    >
      <span aria-hidden="true">{prefix}</span>
      {variant === "count" ? (
        <span data-scroll-count="" aria-hidden="true">
          {final}
        </span>
      ) : (
        <span
          aria-hidden="true"
          style={{ display: "inline-flex", height: "1em", lineHeight: 1, overflow: "hidden" }}
        >
          {[...final].map((char, i) =>
            /\d/.test(char) ? (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  width: ".65em",
                  height: "1em",
                  overflow: "hidden",
                }}
              >
                <span
                  data-scroll-digit={char}
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    transform: `translateY(${-(10 + Number(char)) * 5}%)`,
                  }}
                >
                  {Array.from({ length: 20 }, (_, j) => (
                    <span key={j} style={{ height: "1em", flexShrink: 0, textAlign: "center" }}>
                      {j % 10}
                    </span>
                  ))}
                </span>
              </span>
            ) : (
              <span key={i}>{char}</span>
            ),
          )}
        </span>
      )}
      <span aria-hidden="true">{suffix}</span>
    </span>
  );
}

// @zeus-internal
export const scrollClamp = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0);
export const scrollLerp = (a: number, b: number, p: number) => a + (b - a) * scrollClamp(p);
export const scrollRange = (value: number, start: number, end: number) =>
  start === end ? Number(value >= end) : scrollClamp((value - start) / (end - start));
export const scrollEase = (p: number) => {
  const q = scrollClamp(p);
  return q * q * (3 - 2 * q);
};
export const scrollStagger = (p: number, index: number, count: number, spread = 0.4) => {
  const s = Math.min(0.95, Math.max(0, spread));
  return scrollClamp((p - (index / Math.max(1, count - 1)) * s) / (1 - s));
};
export const scrollRandom = (index: number, seed = 1) => {
  const x = Math.sin((index + 1) * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
};
export interface ScrollFrame {
  x: number;
  y: number;
  width: number;
  height: number;
  rotation?: number;
  radius?: number;
}
export function scrollFrame(
  frames: readonly ScrollFrame[],
  progress: number,
): Required<ScrollFrame> {
  const p = scrollClamp(progress) * Math.max(0, frames.length - 1),
    index = Math.floor(p);
  const a = frames[index] ?? { x: 0, y: 0, width: 100, height: 100 },
    b = frames[Math.min(index + 1, frames.length - 1)] ?? a;
  return {
    x: scrollLerp(a.x, b.x, p - index),
    y: scrollLerp(a.y, b.y, p - index),
    width: scrollLerp(a.width, b.width, p - index),
    height: scrollLerp(a.height, b.height, p - index),
    rotation: scrollLerp(a.rotation ?? 0, b.rotation ?? 0, p - index),
    radius: scrollLerp(a.radius ?? 0, b.radius ?? 0, p - index),
  };
}
/** Color stops accept CSS hex (3/6 digits) or rgb/rgba. Unknown formats hold until the next stop. */
export function scrollMixColor(a: string, b: string, p: number) {
  const parse = (s: string): number[] | null => {
    const hex = s.replace(/^#/, "");
    if (/^[0-9a-f]{3}$/i.test(hex)) return [...hex].map((x) => parseInt(x + x, 16));
    if (/^[0-9a-f]{6}$/i.test(hex)) return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
    const parts = s
      .match(/^rgba?\(([^)]+)\)$/)?.[1]
      ?.match(/[\d.]+/g)
      ?.map(Number);
    return parts && parts.length >= 3 ? parts : null;
  };
  const ca = parse(a),
    cb = parse(b);
  if (!ca || !cb) return p < 1 ? a : b;
  const channels = [0, 1, 2].map((i) => Math.round(scrollLerp(ca[i]!, cb[i]!, p))).join(", ");
  return ca.length > 3 || cb.length > 3
    ? `rgba(${channels}, ${scrollLerp(ca[3] ?? 1, cb[3] ?? 1, p)})`
    : `rgb(${channels})`;
}

